"""
Arduino Code Generator
Converts parsed DuckyScript commands into a complete ESP32-S3 Arduino sketch
that uses USB HID keyboard emulation.
"""

from typing import List
from compiler.duckyscript_parser import Command
from compiler.keycodes import MODIFIERS, SPECIAL_KEYS


class ArduinoGenerator:
    """Generate an ESP32-S3 Arduino .ino file from parsed DuckyScript commands."""

    HEADER = '''\
/*
 * ESP32-S3 USB Rubber Ducky
 * Auto-generated by esp32-ducky toolkit
 *
 * IMPORTANT: For authorized security testing and education ONLY.
 * Using this on systems without explicit permission is illegal.
 *
 * Board:  ESP32-S3 (with native USB)
 * USB Mode: USB-OTG (must be set in Arduino IDE / PlatformIO)
 */

#include "USB.h"
#include "USBHIDKeyboard.h"
#include "USBHIDMouse.h"

USBHIDKeyboard Keyboard;
USBHIDMouse Mouse;

// Built-in LED (varies by board — adjust if needed)
#ifndef LED_BUILTIN
#define LED_BUILTIN 2
#endif

// Optional: trigger pin (wire a button between this pin and GND)
#define TRIGGER_PIN 0

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
  pinMode(TRIGGER_PIN, INPUT_PULLUP);

  // Initialize USB HID Keyboard & Mouse
  Keyboard.begin();
  Mouse.begin();
  USB.begin();

  // Wait for USB to enumerate on the host
  delay(1500);

  // Visual indicator: blink before payload
  digitalWrite(LED_BUILTIN, HIGH);
  delay(200);
  digitalWrite(LED_BUILTIN, LOW);
  delay(200);

  // === PAYLOAD START ===
  executePayload();
  // === PAYLOAD END ===

  // Visual indicator: payload complete
  for (int i = 0; i < 3; i++) {
    digitalWrite(LED_BUILTIN, HIGH);
    delay(100);
    digitalWrite(LED_BUILTIN, LOW);
    delay(100);
  }
}

void loop() {
  // Payload runs once in setup().
  // Optional: re-trigger on button press
  if (digitalRead(TRIGGER_PIN) == LOW) {
    delay(500); // debounce
    executePayload();
    delay(2000);
  }
}

void typeString(const char* str) {
  for (int i = 0; str[i] != \'\\0\'; i++) {
    Keyboard.press(str[i]);
    delay(5);  // small inter-key delay for reliability
    Keyboard.release(str[i]);
    delay(5);
  }
}

void moveToScreenPercent(float pctX, float pctY, int screenW, int screenH) {
  // 1. Reset cursor to top-left corner (0, 0)
  for (int i = 0; i < 25; i++) {
    Mouse.move(-120, -120);
    delay(5);
  }
  delay(100);

  // 2. Calculate target pixels from calibrated resolution
  int targetX = (int)((pctX / 100.0f) * screenW);
  int targetY = (int)((pctY / 100.0f) * screenH);

  // 3. Step towards target coordinates in safe increments
  while (targetX > 0 || targetY > 0) {
    int stepX = (targetX > 100) ? 100 : targetX;
    int stepY = (targetY > 100) ? 100 : targetY;
    Mouse.move(stepX, stepY);
    targetX -= stepX;
    targetY -= stepY;
    delay(5);
  }
  delay(50);
}

void executePayload() {
'''

    FOOTER = '''\
}
'''

    def __init__(self):
        self.indent = "  "

    def generate(self, commands: List[Command], default_delay: int = 0) -> str:
        """Generate complete Arduino sketch from command list."""
        lines = []
        lines.append(self.HEADER)

        screen_w = 1080
        screen_h = 2400
        prev_cmd = None

        for cmd in commands:
            # Insert default delay between commands (if set)
            if default_delay > 0 and prev_cmd is not None:
                lines.append(f"{self.indent}delay({default_delay});")

            # Add a comment showing the original DuckyScript line
            lines.append(f"{self.indent}// Line {cmd.line_num}: {cmd.cmd_type}")

            if cmd.cmd_type == "screen_size":
                screen_w = cmd.mouse_x
                screen_h = cmd.mouse_y
                lines.append(f"{self.indent}// Screen resolution set to {screen_w}x{screen_h}")
                lines.append("")

            elif cmd.cmd_type == "mouse_pos_pct":
                parts = cmd.value.split(",")
                px = float(parts[0])
                py = float(parts[1])
                lines.append(f"{self.indent}moveToScreenPercent({px}f, {py}f, {screen_w}, {screen_h});")
                lines.append("")

            if cmd.cmd_type == "delay":
                lines.append(f"{self.indent}delay({cmd.delay_ms});")
                lines.append("")

            elif cmd.cmd_type == "default_delay":
                default_delay = cmd.delay_ms
                lines.append(
                    f"{self.indent}// Default delay set to {cmd.delay_ms}ms"
                )
                lines.append("")

            elif cmd.cmd_type == "string":
                escaped = self._escape_string(cmd.value)
                lines.append(f'{self.indent}typeString("{escaped}");')
                lines.append("")

            elif cmd.cmd_type == "stringln":
                escaped = self._escape_string(cmd.value)
                lines.append(f'{self.indent}typeString("{escaped}");')
                lines.append(f"{self.indent}Keyboard.press(KEY_RETURN);")
                lines.append(f"{self.indent}delay(10);")
                lines.append(f"{self.indent}Keyboard.release(KEY_RETURN);")
                lines.append("")

            elif cmd.cmd_type == "keypress":
                for key in cmd.keys:
                    key_const = self._resolve_key(key)
                    lines.append(
                        f"{self.indent}Keyboard.press({key_const});"
                    )
                lines.append(f"{self.indent}delay(30);")
                for key in reversed(cmd.keys):
                    key_const = self._resolve_key(key)
                    lines.append(
                        f"{self.indent}Keyboard.release({key_const});"
                    )
                lines.append("")

            elif cmd.cmd_type == "mouse_move":
                lines.append(f"{self.indent}Mouse.move({cmd.mouse_x}, {cmd.mouse_y});")
                lines.append(f"{self.indent}delay(20);")
                lines.append("")

            elif cmd.cmd_type == "mouse_click":
                btn = "MOUSE_LEFT" if cmd.mouse_button == "LEFT" else ("MOUSE_RIGHT" if cmd.mouse_button == "RIGHT" else "MOUSE_MIDDLE")
                lines.append(f"{self.indent}Mouse.click({btn});")
                lines.append(f"{self.indent}delay(50);")
                lines.append("")

            elif cmd.cmd_type == "mouse_scroll":
                lines.append(f"{self.indent}Mouse.move(0, 0, {cmd.mouse_wheel});")
                lines.append(f"{self.indent}delay(30);")
                lines.append("")

            elif cmd.cmd_type == "combo":
                # Press all modifiers first, then keys
                for mod in cmd.modifiers:
                    mod_const = MODIFIERS[mod]
                    lines.append(
                        f"{self.indent}Keyboard.press({mod_const});"
                    )
                for key in cmd.keys:
                    key_const = self._resolve_key(key)
                    lines.append(
                        f"{self.indent}Keyboard.press({key_const});"
                    )
                lines.append(f"{self.indent}delay(30);")
                # Release in reverse order
                for key in reversed(cmd.keys):
                    key_const = self._resolve_key(key)
                    lines.append(
                        f"{self.indent}Keyboard.release({key_const});"
                    )
                for mod in reversed(cmd.modifiers):
                    mod_const = MODIFIERS[mod]
                    lines.append(
                        f"{self.indent}Keyboard.release({mod_const});"
                    )
                lines.append("")

            elif cmd.cmd_type == "repeat":
                if prev_cmd:
                    # Wrap previous command in a for loop
                    lines.append(
                        f"{self.indent}// Repeat previous command "
                        f"{cmd.repeat_count} more time(s)"
                    )
                    # We regenerate the previous command inside a loop
                    repeat_code = self._generate_single(prev_cmd)
                    lines.append(
                        f"{self.indent}for (int _r = 0; _r < {cmd.repeat_count}; _r++) {{"
                    )
                    for rc in repeat_code:
                        lines.append(f"{self.indent}  {rc}")
                    lines.append(f"{self.indent}}}")
                lines.append("")

            prev_cmd = cmd

        lines.append(self.FOOTER)
        return "\n".join(lines)

    def _generate_single(self, cmd: Command) -> List[str]:
        """Generate code lines for a single command (used by REPEAT)."""
        lines = []
        if cmd.cmd_type == "string":
            escaped = self._escape_string(cmd.value)
            lines.append(f'typeString("{escaped}");')
        elif cmd.cmd_type == "stringln":
            escaped = self._escape_string(cmd.value)
            lines.append(f'typeString("{escaped}");')
            lines.append("Keyboard.press(KEY_RETURN);")
            lines.append("delay(10);")
            lines.append("Keyboard.release(KEY_RETURN);")
        elif cmd.cmd_type == "keypress":
            for key in cmd.keys:
                key_const = self._resolve_key(key)
                lines.append(f"Keyboard.press({key_const});")
            lines.append("delay(30);")
            for key in reversed(cmd.keys):
                key_const = self._resolve_key(key)
                lines.append(f"Keyboard.release({key_const});")
        elif cmd.cmd_type == "combo":
            for mod in cmd.modifiers:
                lines.append(f"Keyboard.press({MODIFIERS[mod]});")
            for key in cmd.keys:
                key_const = self._resolve_key(key)
                lines.append(f"Keyboard.press({key_const});")
            lines.append("delay(30);")
            for key in reversed(cmd.keys):
                key_const = self._resolve_key(key)
                lines.append(f"Keyboard.release({key_const});")
            for mod in reversed(cmd.modifiers):
                lines.append(f"Keyboard.release({MODIFIERS[mod]});")
        elif cmd.cmd_type == "delay":
            lines.append(f"delay({cmd.delay_ms});")
        return lines

    def _resolve_key(self, key: str) -> str:
        """Resolve a key name to its Arduino constant."""
        upper = key.upper()
        if upper in MODIFIERS:
            return MODIFIERS[upper]
        if upper in SPECIAL_KEYS:
            return SPECIAL_KEYS[upper]
        # Single character key — use the character literal
        if len(key) == 1:
            return f"'{key}'"
        raise ValueError(f"Unknown key: {key}")

    def _escape_string(self, s: str) -> str:
        """Escape a string for C/Arduino."""
        return (
            s.replace("\\", "\\\\")
            .replace('"', '\\"')
            .replace("\n", "\\n")
            .replace("\r", "\\r")
            .replace("\t", "\\t")
        )
